export const directoryBrands: DirectoryBrand[] = brandRecords.map(brand => ({
  ...brand,
  bg: brandThemes[brand.id].background,
  ink: brandThemes[brand.id].ink,
  theme: brandThemes[brand.id],
}));

export function findDirectoryBrand(value: string) {
  return directoryBrands.find(brand => brand.id === value || brand.name.toLocaleLowerCase() === value.toLocaleLowerCase());
}
